def analyze_customers(records: list[dict]) -> dict:
    if not records:
        return {'total_users': 0, 'high_value_count': 0, 'high_value_pct': 0.0}
    all_users = set()
    high_value_users = set()
    for r in records:
        uid = r['user_id']
        all_users.add(uid)
        if r['amount'] >= 100.0 and r['days_active'] >= 30:
            high_value_users.add(uid)
    total = len(all_users)
    hv_count = len(high_value_users)
    pct = round((hv_count / total * 100.0), 2) if total > 0 else 0.0
    return {'total_users': total, 'high_value_count': hv_count, 'high_value_pct': pct}
